const text = $('Base Articolo').first().json.message.content || '';
const metatext = $input.first().json.message.content || '';

// Regex robuste per i tre campi
const titoloMatch = text.match(/^\s*Titolo\s*:\s*(.+?)\s*$/im);
const metaTitleMatch = metatext.match(/^\s*Meta\s*Title\s*:\s*(.+?)\s*$/im);
const metaDescMatch = metatext.match(/^\s*Meta\s*Description\s*:\s*(.+?)\s*$/im);

return [
  {
    json: {
      titolo: titoloMatch ? titoloMatch[1].trim() : '',
      meta_title: metaTitleMatch ? metaTitleMatch[1].trim() : '',
      meta_description: metaDescMatch ? metaDescMatch[1].trim() : ''
    }
  }
];

